const i18n = {
  currentLang: "en",

  // Exposed for backward-compatibility with tests that inspect translations directly
  translations: _resources,

  /** Translate a key with optional {var} interpolation.
   *  Respects this.currentLang so tests can do: i18n.currentLang = "zh"
   *  without needing to call setLanguage().
   *
   *  Returns the key itself when:
   *  - currentLang is not a supported locale
   *  - the key does not exist in the locale
   */
  t(key, vars) {
    if (!SUPPORTED.includes(this.currentLang)) return key;
    const dict = _resources[this.currentLang];
    if (!dict) return key;
    let text = dict[key];
    if (text === undefined) return key;
    if (vars) {
      Object.keys(vars).forEach((k) => {
        text = text.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
      });
    }
    return text;
  },

  // setLanguage stays as a programmatic hook (useful for tests + future
  // need), but no longer persists to localStorage. The desktop app
  // follows the system locale; no in-app override.
  setLanguage(lang) {
    if (!SUPPORTED.includes(lang)) return;
    this.currentLang = lang;
    // Update <html lang=""> so CSS :lang() picks the right CJK font
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = lang;
    }
    this.updateUI();
  },

  /** Detect and apply the correct language (async — uses Electron IPC if
   *  available). 2026-05-16: localStorage 'danmu-lang' override removed;
   *  Electron desktop follows the system locale via app.getLocale(). If
   *  a stale 'danmu-lang' key exists from a previous version, sweep it. */
  async loadLanguage() {
    if (typeof localStorage !== "undefined") {
      try { localStorage.removeItem("danmu-lang"); } catch (_) {}
    }

    // Try Electron system locale first
    try {
      if (
        typeof window !== "undefined" &&
        window.API &&
        typeof window.API.getSystemLocale === "function"
      ) {
        const systemLocale = await window.API.getSystemLocale();
        console.log("[i18n] System locale:", systemLocale);
        const detected = this._detectLangFromLocale(systemLocale);
        if (detected) {
          this.currentLang = detected;
          return;
        }
      }
    } catch (err) {
      console.warn("[i18n] getSystemLocale failed, falling back:", err);
    }

    // Browser fallback
    const browserLang =
      typeof navigator !== "undefined"
        ? navigator.language || navigator.userLanguage
        : "";
    console.log("[i18n] Browser language:", browserLang);
    const detected = this._detectLangFromLocale(browserLang);
    if (detected) this.currentLang = detected;
  },

  _detectLangFromLocale(locale) {
    if (!locale) return null;
    if (locale.startsWith("zh")) return "zh";
    if (locale.startsWith("ja")) return "ja";
    if (locale.startsWith("ko")) return "ko";
    return null;
  },

  updateUI() {
    if (typeof document === "undefined") return;
    // Keep <html lang=""> in sync so CSS :lang() picks the right CJK font
    if (document.documentElement) {
      document.documentElement.lang = this.currentLang;
    }
    document.querySelectorAll("[data-i18n]").forEach((el) => {
      const key = el.getAttribute("data-i18n");
      const text = this.t(key);
      if (el.tagName === "INPUT" || el.tagName === "TEXTAREA") {
        el.placeholder = text;
      } else {
        el.textContent = text;
      }
    });
    document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
      const key = el.getAttribute("data-i18n-placeholder");
      el.placeholder = this.t(key);
    });
  },
};

if (typeof module !== "undefined" && module.exports) {
  module.exports = i18n;
}
